package com.asthereon.green_thumb;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

import java.awt.*;

@ConfigGroup("greenthumb")
public interface GreenThumbConfig extends Config
{
	@ConfigItem(
			position = 0,
			keyName = "showItemName",
			name = "Show Item Name",
			description = "Show the name of the seed on hover."
	)
	default boolean showItemName() {
		return true;
	}

	@ConfigItem(
			position = 1,
			keyName = "showLevelRequirement",
			name = "Show Level Requirement",
			description = "Show the level requirement for a seed on hover."
	)
	default boolean showLevelRequirement() {
		return true;
	}

	@ConfigItem(
			position = 2,
			keyName = "showSeedType",
			name = "Show Seed Type",
			description = "Show the seed type for a seed on hover."
	)
	default boolean showSeedType() {
		return true;
	}

	@ConfigItem(
			position = 3,
			keyName = "showSeedsPerPatch",
			name = "Show Seeds Per Patch",
			description = "Show the seeds required to plant a patch for a seed on hover."
	)
	default boolean showSeedsPerPatch() {
		return true;
	}

	@ConfigItem(
			position = 4,
			keyName = "showGrowthTime",
			name = "Show Growth Time",
			description = "Show the average time for a seed to grow."
	)
	default boolean showGrowthTime() {
		return true;
	}

	@ConfigItem(
			position = 5,
			keyName = "showGrowthCycles",
			name = "Show Growth Cycles",
			description = "Show the average number and length of the growth cycles for a seed."
	)
	default boolean showGrowthCycles() {
		return true;
	}

	@ConfigItem(
			position = 6,
			keyName = "showProtectionPayment",
			name = "Show Protection Payment",
			description = "Show the payment for a farmer to protect a seed on hover."
	)
	default boolean showProtectionPayment() {
		return true;
	}

	@ConfigItem(
			position = 7,
			keyName = "showProtectionFlowers",
			name = "Show Protection Flowers",
			description = "Show the flowers that can be used to protect a seed on hover."
	)
	default boolean showProtectionFlowers() {
		return true;
	}

	@ConfigItem(
			position = 8,
			keyName = "showUses",
			name = "Show Uses",
			description = "Show the uses for the crop harvested from a seed on hover."
	)
	default boolean showUses() {
		return true;
	}

	@ConfigItem(
			position = 9,
			keyName = "metRequirementColor",
			name = "Met Requirement Color",
			description = "Configures the text color used when a requirement is met"
	)
	default Color metRequirementColor()
	{
		return Color.GREEN;
	}

	@ConfigItem(
			position = 10,
			keyName = "notMetRequirementColor",
			name = "Not Met Requirement Color",
			description = "Configures the text color used when a requirement is not met"
	)
	default Color notMetRequirementColor()
	{
		return Color.RED;
	}

	@ConfigItem(
			position = 11,
			keyName = "itemNameColor",
			name = "Item Name Color",
			description = "Configures the text color used for the name of the item on hover."
	)
	default Color itemNameColor() { return Color.WHITE; }

	@ConfigItem(
			position = 12,
			keyName = "showPlantXP",
			name = "Show Plant XP",
			description = "Show the experience gained for planting the seed on hover."
	)
	default boolean showPlantXP() {
		return false;
	}

	@ConfigItem(
			position = 13,
			keyName = "showCheckHealthXP",
			name = "Show Check Health XP",
			description = "Show the experience gained for checking the health of the seed on hover (if applicable)."
	)
	default boolean showCheckHealthXP() {
		return true;
	}

	@ConfigItem(
			position = 14,
			keyName = "showHarvestXP",
			name = "Show Harvest XP",
			description = "Show the experience gained for each harvest of the seed on hover (if applicable)."
	)
	default boolean showHarvestXP() {
		return false;
	}
}

package com.asthereon.green_thumb;

import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import org.apache.commons.lang3.StringUtils;

import javax.inject.Inject;
import java.awt.*;
import java.util.Optional;

public class GreenThumbOverlay extends Overlay {

    private final Client client;
    private final TooltipManager tooltipManager;
    private final ItemManager itemManager;
    private final GreenThumbConfig config;

    private final StringBuilder stringBuilder = new StringBuilder();

    @Inject
    GreenThumbOverlay(Client client, TooltipManager tooltipManager, ItemManager itemManager, GreenThumbConfig config)
    {
        setPosition(OverlayPosition.DYNAMIC);
        this.client = client;
        this.tooltipManager = tooltipManager;
        this.itemManager = itemManager;
        this.config = config;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.isMenuOpen())
        {
            return null;
        }

        final MenuEntry[] menuEntries = client.getMenu().getMenuEntries();
        final int last = menuEntries.length - 1;

        if (last < 0)
        {
            return null;
        }

        final MenuEntry menuEntry = menuEntries[last];

        if (StringUtils.isEmpty(menuEntry.getTarget()) ||
                menuEntry.getOption().contains("View") ||
                menuEntry.getParam0() < 0)
        {
            // These are interface buttons, don't render the overlay.
            return null;
        }

        final MenuAction action = menuEntry.getType();
        final int componentID = menuEntry.getParam1();

        switch (action)
        {
            case WIDGET_TARGET:
            case WIDGET_TARGET_ON_WIDGET:
            case CC_OP:
            case CC_OP_LOW_PRIORITY:
                Optional<ItemContainer> container = getContainer(componentID);
                if (container.isPresent())
                {
                    Optional<Item> item = getContainerItem(container.get(), menuEntry.getParam0());
                    if (item.isPresent())
                    {
                        String itemName = stripExtra(itemManager.getItemComposition(item.get().getId()).getName());

                        Seed seed = Seed.getSeedFromItemName(itemName);
                        if (seed != null) {
                            stringBuilder.append(seed.getTooltip(config, client, item.get().getQuantity()));
                        }
                    }
                    if (stringBuilder.length() > 0)
                    {
                        addTooltip();
                    }
                    break;
                }
                break;
        }
        return null;
    }

    private Optional<ItemContainer> getContainer(int widgetId)
    {
        int interfaceID = WidgetUtil.componentToInterface(widgetId);
        if (interfaceID == InterfaceID.INVENTORY || interfaceID == InterfaceID.BANKSIDE || interfaceID == InterfaceID.SEED_VAULT_DEPOSIT) {
            return Optional.ofNullable(client.getItemContainer(InventoryID.INV));
        }
        else if (interfaceID == InterfaceID.BANKMAIN) {
            return Optional.ofNullable(client.getItemContainer(InventoryID.BANK));
        }
        else if (interfaceID == InterfaceID.SEED_VAULT) {
            return Optional.ofNullable(client.getItemContainer(InventoryID.SEED_VAULT));
        }
        else if (interfaceID == InterfaceID.SHARED_BANK) {
            return Optional.ofNullable(client.getItemContainer(InventoryID.INV_GROUP_TEMP));
        }
        else if (interfaceID == InterfaceID.HOSIDIUS_SEEDBOX) {
            return Optional.ofNullable(client.getItemContainer(InventoryID.SEED_BOX));
        }
        return Optional.empty();
    }

    private Optional<Item> getContainerItem(ItemContainer container, int itemId)
    {
        return Optional.ofNullable(container.getItem(itemId));
    }

    private void addTooltip()
    {
        tooltipManager.add(new Tooltip(stringBuilder.toString()));
        stringBuilder.setLength(0);
    }

    private String stripExtra(String item)
    {
        String stripped = item.replaceAll("\\s?\\(\\d\\)", "");
        return stripped.substring(0, 1).toUpperCase() + stripped.substring(1);
    }
}

package com.asthereon.green_thumb;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Green Thumb"
)
public class GreenThumbPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private GreenThumbConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private GreenThumbOverlay greenThumbOverlay;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(greenThumbOverlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(greenThumbOverlay);
	}

	@Provides
	GreenThumbConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GreenThumbConfig.class);
	}
}

package com.asthereon.green_thumb;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class GreenThumbPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(GreenThumbPlugin.class);
		RuneLite.main(args);
	}
}
